<script setup lang="ts">
import {ref,onMounted} from 'vue'
import Button from 'primevue/button'
import {api,post,type Book} from '../api'
interface ImportRow {id:number;data:Book;result:string;existing:boolean}
const sessions=ref<{id:number;created_at:string}[]>([]),session=ref<number|null>(null),rows=ref<ImportRow[]>([]),selected=ref<number[]>([]),copies=ref<number[]>([]),error=ref(''),busy=ref(false),progress=ref('')
async function sessionsLoad(){sessions.value=await api('/imports')}
async function open(id:number){busy.value=true;error.value='';try{session.value=id;rows.value=(await api<{rows:ImportRow[]}>('/imports/'+id)).rows;selected.value=[];copies.value=[]}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';try{if(file.size>3*1024*1024)throw new Error('CSV deve ter até 3 MB.');const body=new FormData();body.append('file',file);const data=await api<{id:number}>('/imports',{method:'POST',body});await open(data.id);await sessionsLoad()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function process(){if(!session.value||!selected.value.length)return;if(!confirm(`Importar ${selected.value.length} livro(s) selecionado(s)? Livros existentes serão ignorados, salvo cópia explícita.`))return;busy.value=true;error.value='';const actions=selected.value.map(id=>({id,action:copies.value.includes(id)?'copy':'import'}));try{for(let i=0;i<actions.length;i+=25){await post('/imports/'+session.value+'/process',{actions:actions.slice(i,i+25)});progress.value=`${Math.min(i+25,actions.length)} de ${actions.length} processados.`}await open(session.value)}catch(e){error.value=(e as Error).message;progress.value+=' Você pode retomar esta importação sem duplicar as linhas concluídas.'}finally{busy.value=false}}
onMounted(async()=>{try{await sessionsLoad()}catch(e){error.value=(e as Error).message}})
</script>
<template><div class="page-heading"><div><div class="eyebrow">SUA COLEÇÃO, UM PASSO ADIANTE</div><h1>Importar do Goodreads</h1><p class="muted">Selecione apenas os livros que você possui.</p></div></div><div class="panel"><p>Exporte no Goodreads: <b>My Books → Import and Export → Export Library</b>.</p><label>Enviar CSV (até 3 MB / 5.000 linhas)<input type="file" accept=".csv,text/csv" :disabled="busy" @change="upload"></label><p class="muted">Criamos um exemplar por livro escolhido. Depois você pode informar a localização e adicionar outras cópias.</p><div v-if="sessions.length" class="actions"><span class="muted">Retomar:</span><Button v-for="item in sessions" :key="item.id" :label="'Importação #'+item.id" text size="small" @click="open(item.id)"/></div></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="progress" class="notice" role="status">{{progress}}</p><template v-if="rows.length"><div class="section-heading"><h2>{{rows.length}} registros para revisar</h2><Button label="Importar selecionados" class="primary" :disabled="!selected.length" :loading="busy" @click="process"/></div><p class="muted">Selecione os livros possuídos. “Outra cópia” só é necessária para adicionar um exemplar de livro já cadastrado.</p><div class="table-wrap panel"><table class="data-table"><thead><tr><th>Importar</th><th>Livro</th><th>ISBN</th><th>Correspondência</th><th>Outra cópia</th><th>Resultado</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><input type="checkbox" :value="row.id" v-model="selected" :disabled="!!row.result||busy" :aria-label="'Importar '+row.data.title"></td><td><b>{{row.data.title}}</b><br><span class="muted">{{row.data.authors.join(', ')}}</span></td><td>{{row.data.isbn||'Sem ISBN'}}</td><td>{{row.existing?'Já cadastrado':'Novo'}}</td><td><input v-if="row.existing&&!row.result" type="checkbox" v-model="copies" :value="row.id" :aria-label="'Adicionar outra cópia de '+row.data.title"></td><td>{{({created:'Criado',existing:'Já existente · ignorado',skipped:'Ignorado'} as Record<string,string>)[row.result]||'Pendente'}}</td></tr></tbody></table></div></template></template>
